/**
 * JWT Token Utilities for External Gateway
 * 
 * Handles JWT token generation and validation for external form access.
 * Tokens are generated by the Python Runner Service and validated here.
 */

import jwt from "jsonwebtoken";

export interface ExternalTokenPayload {
  executionId: string;
  formId?: number;
  requestId?: number;
  email: string;
  role: "external" | "internal";
  context?: Record<string, any>;
  iat?: number;
  exp?: number;
}

/**
 * Validate JWT token from external requests
 * Returns decoded payload if valid, throws error if invalid
 */
export function validateExternalToken(token: string): ExternalTokenPayload {
  if (!process.env.JWT_SECRET) {
    throw new Error("JWT_SECRET environment variable is not set");
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET) as ExternalTokenPayload;
    
    // Validate required fields
    if (!decoded.executionId || !decoded.email || !decoded.role) {
      throw new Error("Invalid token payload structure");
    }

    return decoded;
  } catch (error: any) {
    if (error.name === "TokenExpiredError") {
      throw new Error("Token has expired");
    }
    if (error.name === "JsonWebTokenError") {
      throw new Error("Invalid token signature");
    }
    throw error;
  }
}

/**
 * Generate JWT token for external access
 * This is primarily used by the Python Runner Service, but provided here for testing/utility purposes
 */
export function generateExternalToken(payload: Omit<ExternalTokenPayload, "iat" | "exp">): string {
  if (!process.env.JWT_SECRET) {
    throw new Error("JWT_SECRET environment variable is not set");
  }

  const tokenPayload: ExternalTokenPayload = {
    ...payload
  };

  // Default expiration: 48 hours (configurable per form via securityConfig)
  const expiresIn = "48h";

  return jwt.sign(tokenPayload, process.env.JWT_SECRET, {
    expiresIn,
  });
}
